//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_supervision(value: *mut Isolette_Thermostat_Rust::RegulatorSupervision) -> bool;
  fn put_diagnostic_facts(value: *mut Isolette_Thermostat_Rust::RegulatorDiagnosticFacts) -> bool;
}

pub fn unsafe_get_supervision() -> Isolette_Thermostat_Rust::RegulatorSupervision
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::RegulatorSupervision = &mut Isolette_Thermostat_Rust::RegulatorSupervision::default();
    get_supervision(value);
    return *value;
  }
}

pub fn unsafe_put_diagnostic_facts(value: &Isolette_Thermostat_Rust::RegulatorDiagnosticFacts) -> bool
{
  unsafe {
    return put_diagnostic_facts(value as *const Isolette_Thermostat_Rust::RegulatorDiagnosticFacts as *mut Isolette_Thermostat_Rust::RegulatorDiagnosticFacts);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_supervision: Mutex<Option<Isolette_Thermostat_Rust::RegulatorSupervision>> = Mutex::new(None);
  pub static ref OUT_diagnostic_facts: Mutex<Option<Isolette_Thermostat_Rust::RegulatorDiagnosticFacts>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_supervision.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_diagnostic_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_supervision(value: *mut Isolette_Thermostat_Rust::RegulatorSupervision) -> bool
{
  unsafe {
    let guard = IN_supervision.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_diagnostic_facts(value: *mut Isolette_Thermostat_Rust::RegulatorDiagnosticFacts) -> bool
{
  unsafe {
    *OUT_diagnostic_facts.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
